<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Pipeline_spp_invoice_model extends CI_Model {
 /** Mengambil SPP sesuai area, tanpa batas 100 arsip terbaru. */
 public function candidates($invoice=null){$ids=array_column($this->billing->branches(),'SpbbID');if(!$ids)return array();$rows=$this->db->where_in('SpbbID',$ids)->where('Status','CONFIRMED')->order_by('DeliveryDate','DESC')->get('PipelineSppCapture')->result_array();return array_values(array_filter($rows,function($r)use($invoice){try{$this->available($r,$invoice);return true;}catch(Exception $e){return false;}}));}
 public function key($r){$lo=trim((string)$r['LONumber']);$shipment=trim((string)$r['ShipmentNo']);if($lo===''&&$shipment==='')throw new RuntimeException('Lengkapi referensi Surat Pengantar Pengiriman pada SPP.');return ($lo!==''?'LO:':'SHIP:').mb_strtoupper($lo!==''?$lo:$shipment);}
 /** Mencegah tagihan berulang lintas unggahan SPP, DO dan berita acara. */
 public function available($r,$invoice=null){
  $key=$this->key($r);$lo=mb_strtoupper(trim((string)$r['LONumber']));$shipment=mb_strtoupper(trim((string)$r['ShipmentNo']));$b=$this->db->query("SELECT TOP 1 I.InvoiceID FROM PipelineSppInvoice I JOIN PipelineSppCapture C ON C.CaptureID=I.CaptureID WHERE I.SpbbID=? AND (I.CaptureID=? OR I.SourceKey=? OR (?<>'' AND UPPER(LTRIM(RTRIM(C.LONumber)))=?) OR (?<>'' AND UPPER(LTRIM(RTRIM(C.ShipmentNo)))=?))",array($r['SpbbID'],$r['CaptureID'],$key,$lo,$lo,$shipment,$shipment))->row_array();if($b&&(!$invoice||(int)$b['InvoiceID']!==(int)$invoice))throw new RuntimeException('Surat Pengantar Pengiriman sudah ditagihkan.');
  $op=$this->db->query("SELECT TOP 1 I.InvoiceID FROM PipelineOperation O JOIN PipelineOperationInvoice I ON I.OperationID=O.OperationID LEFT JOIN PipelineSppCapture C ON C.CaptureID=O.CaptureID WHERE O.Kind='BASTB' AND O.SpbbID=? AND (O.CaptureID=? OR O.SourceKey=? OR (?<>'' AND UPPER(LTRIM(RTRIM(C.LONumber)))=?) OR (?<>'' AND UPPER(LTRIM(RTRIM(C.ShipmentNo)))=?))",array($r['SpbbID'],$r['CaptureID'],$key,$lo,$lo,$shipment,$shipment))->row_array();if($op&&(!$invoice||(int)$op['InvoiceID']!==(int)$invoice))throw new RuntimeException('SPP sudah ditagihkan melalui BASTB.');
  $q=$this->db->query("SELECT TOP 1 I.InvoiceID FROM PipelineInvoiceDelivery I JOIN PipelineDelivery D ON D.DeliveryID=I.DeliveryID LEFT JOIN PipelineDocument P ON P.DeliveryID=D.DeliveryID AND P.DocumentType='SPP' WHERE D.SpbbID=? AND (D.DeliveryID=? OR (P.LoadingReference<>'' AND UPPER(LTRIM(RTRIM(P.LoadingReference)))=?) OR (?<>'' AND UPPER(LTRIM(RTRIM(P.ReferenceNo)))=?) OR EXISTS(SELECT 1 FROM PipelineSppCapture C WHERE C.DeliveryID=D.DeliveryID AND ((?<>'' AND UPPER(LTRIM(RTRIM(C.LONumber)))=?) OR (?<>'' AND UPPER(LTRIM(RTRIM(C.ShipmentNo)))=?))))",array($r['SpbbID'],(int)$r['DeliveryID'],$lo,$shipment,$shipment,$lo,$lo,$shipment,$shipment));if($q->row_array())throw new RuntimeException('SPP sudah ditagihkan melalui DO.');
 }
 /** Menghitung tarif dan PPN dari SPP terkonfirmasi; tidak memerlukan BASTB/RDT. */
 public function quote($ids,$invoice=null){
  if(count($ids)>500||count($ids)!==count(array_unique($ids)))throw new RuntimeException('Pilihan SPP harus unik, maksimal 500.');
  $out=array('branch'=>null,'company'=>null,'dates'=>array(),'liters'=>0,'subtotal'=>0,'tax'=>0,'lines'=>array(),'links'=>array());$keys=array();
  foreach($ids as $id){$r=$this->spp->capture($id);if(!$r||$r['Status']!=='CONFIRMED')throw new RuntimeException('SPP tidak ditemukan / belum dikonfirmasi.');$this->available($r,$invoice);$key=$this->key($r);if(isset($keys[$key]))throw new RuntimeException('Surat Pengantar Pengiriman yang sama dipilih lebih dari sekali.');$keys[$key]=true;foreach(array('LONumber','ShipmentNo') as $column){$ref=mb_strtoupper(trim((string)$r[$column]));if($ref==='')continue;$identity=$column.':'.$ref;if(isset($keys[$identity]))throw new RuntimeException('Referensi Surat Pengantar Pengiriman yang sama dipilih lebih dari sekali.');$keys[$identity]=true;}
   $company=trim((string)$r['Buyer']);$date=substr((string)$r['DeliveryDate'],0,10);$q=(float)$r['OrderedLiters'];if($company===''||!$this->pipeline_finance->date_valid($date)||$q<=0)throw new RuntimeException('Lengkapi pembeli, tanggal dan volume SPP sebelum ditagihkan.');
   if($out['branch']!==null&&($out['branch']!==(int)$r['SpbbID']||$out['company']!==$company))throw new RuntimeException('SPP harus satu area dan perusahaan penagihan (Pembeli SPP).');$out['branch']=(int)$r['SpbbID'];$out['company']=$company;$out['dates'][]=$date;$out['liters']+=$q;
   $rate=$this->billing->rate('FUEL_ADMIN',$date,$r['SpbbID']);$vat=$this->billing->rate('VAT',$date,$r['SpbbID']);$qty=$this->pipeline_finance->spp_quantity($r['OrderedLiters'],$rate['Unit'],$r['DensityObs']);$amount=$this->pipeline_finance->amount($qty,$rate['Amount']);$tax=$this->pipeline_finance->amount($amount/100,$vat['Amount']);$ref='SPP #'.$r['CaptureID'].' / LO '.$r['LONumber'].' / DO-Shipment '.$r['ShipmentNo'];
   $out['lines'][]=array('ServiceCode'=>'FUEL_ADMIN','Description'=>$rate['ServiceName'].' — '.$ref,'Quantity'=>$qty,'Unit'=>$rate['Unit'],'Rate'=>$rate['Amount'],'RateID'=>$rate['RateID'],'Amount'=>$amount);
   $out['lines'][]=array('ServiceCode'=>'VAT','Description'=>'PPN Jasa Administrasi BBM','Quantity'=>$amount,'Unit'=>'Dasar Rp','Rate'=>$vat['Amount'],'RateID'=>$vat['RateID'],'Amount'=>$tax);$out['subtotal']+=$amount;$out['tax']+=$tax;$out['links'][]=array('CaptureID'=>(int)$id,'SpbbID'=>(int)$r['SpbbID'],'SourceKey'=>$key,'Snapshot'=>json_encode($r,JSON_UNESCAPED_UNICODE));
  }return $out;
 }
}
